solution.code:
public class Main {
    static long missing(int[] a) {
        int n = a.length;
        long expected = (long) n * (n + 1) / 2;
        long actual = 0;
        for (int x : a) {
            actual += x;
        }
        return expected - actual;
    }

    public static void main(String[] args) {
        int[] a = new int[100000];
        int index = 0;
        for (int v = 0; v <= 100000; v++) {
            if (v != 77777) {
                a[index++] = v;
            }
        }
        System.out.println(missing(a));
    }
}
